$:node <<'NODE'
"use strict";
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{execFileSync}=require('node:child_process');
const repo='BestNameYet/Terminals',id='6ae9dd85-7ff0-83e8-90c3-4592305a2362';
const runs=[41653897500,41653902184],names=['response.html','conversation-raw.json','linear-conversation.json','conversation.json','conversation.md','diagnostics.json','receipt.json','execution.json'];
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const results=[],fingerprints={};
for(const run of runs){
  const status=JSON.parse(execFileSync('gh',['run','view',String(run),'-R',repo,'--json','status,conclusion'],{encoding:'utf8'}));
  assert.equal(status.status,'completed'); assert.equal(status.conclusion,'success');
  const rel='workspaces/shared-conversations/'+id+'/'+run+'-1';
  const dir=path.resolve(rel);
  assert(fs.statSync(dir).isDirectory());
  const receipt=JSON.parse(fs.readFileSync(path.join(dir,'receipt.json')));
  const execution=JSON.parse(fs.readFileSync(path.join(dir,'execution.json')));
  assert.equal(receipt.run_id,String(run));assert.equal(receipt.write_path,rel);
  assert.equal(execution.run_id,String(run)); assert.equal(execution.errors.length,0);
  assert.equal(receipt.counts.linear_nodes,5912);assert.equal(receipt.counts.selected_visible_messages,592);
  for(const name of names){
    const b=fs.readFileSync(path.join(dir,name)),digest=sha(b);
    if(receipt.files[name]){assert.equal(receipt.files[name].bytes,b.length);assert.equal(receipt.files[name].sha256,digest);}
    if(['linear-conversation.json','conversation.json','conversation.md'].includes(name)){
      (fingerprints[name]??=[]).push(digest);
    }
  }
  const temp=fs.mkdtempSync(path.join(os.tmpdir(),'e2e008-'));
  try {
    execFileSync('gh',['run','download',String(run),'-R',repo,'--name','chatgpt-shared-export-final-attestation-'+run+'-1','--dir',temp],{encoding:'utf8',timeout:90000});
    const att=JSON.parse(fs.readFileSync(path.join(temp,'final-attestation.json')));
    assert.equal(att.verification,'VERIFIED');assert.equal(att.run_id,String(run));
    assert.match(att.published_commit_sha,/^[0-9a-f]{40}$/);
    assert.equal(att.paths.length,8);
    const seen=new Set();
    for(const f of att.paths){
      assert(f.path.startsWith(rel+'/'));
      const name=f.path.slice(rel.length+1);assert(names.includes(name));assert(!seen.has(name));seen.add(name);
      const b=fs.readFileSync(path.join(dir,name));
      assert.equal(f.bytes,b.length);assert.equal(f.sha256,sha(b));assert.equal(f.matched_remote_bytes,true);
    }
    assert.equal(seen.size,8);
    results.push({run_id:run,request_id:receipt.request_id,commit:att.published_commit_sha,files_verified:8,attestation:'VERIFIED',linear_nodes:receipt.counts.linear_nodes,selected_visible:receipt.counts.selected_visible_messages,destination:rel});
  } finally {fs.rmSync(temp,{recursive:true,force:true});}
}
assert.notEqual(results[0].destination,results[1].destination);
assert.notEqual(results[0].commit,results[1].commit);
for(const [file,hashes] of Object.entries(fingerprints))assert.equal(hashes[0],hashes[1],file+' content changed between captures');
console.log(JSON.stringify({schema:'terminals.e2e008.independent-verification.v1',result:'PASS',runs:results,stable_products:Object.keys(fingerprints),verified_file_count:16,distinct_commits:2},null,2));
